package br.com.confirmacao.audit.api;import br.com.confirmacao.audit.application.AuditService;import br.com.confirmacao.shared.api.PageResponse;import org.springdoc.core.annotations.ParameterObject;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/admin/audit-logs")public class AuditLogController{private final AuditService service;public AuditLogController(AuditService s){service=s;}@GetMapping public PageResponse<AuditLogResponse> all(@ParameterObject@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return PageResponse.from(service.findAll(p).map(AuditLogResponse::from));}}
